def _fix16_download_bytes(file_id):

    req = _fix16_drive.files().get_media(
        fileId=file_id
    )

    buf = io.BytesIO()

    dl = MediaIoBaseDownload(
        buf,
        req
    )

    done = False

    while not done:
        _, done = dl.next_chunk()

    return buf.getvalue()
